/* Teaching-session lobby. Professor-approved participant entry. */
window.AssemblyWorkshop=(()=>{
 let client,state,topics=[],timer,poller,offset=0,ringKey='',audio,loading=false,active=false;
 const dialog=document.createElement('dialog');dialog.className='live-room-dialog';dialog.setAttribute('aria-label','Teaching session lobby');document.body.append(dialog);
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const el=id=>dialog.querySelector('#'+id);
 const labels={preparation:'Prepare classrooms',prebrief:'Main lobby: prebrief',negotiation:'Classroom negotiation',report:'Classroom report writing',debrief:'Main lobby: debrief',finished:'Session complete'};
 const rpc=async(name,args={})=>{const {data,error}=await client.rpc(name,args);if(error)throw error;return data};
 const button=(text,action,value='')=>'<button type="button" class="secondary" data-workshop="'+action+'" data-value="'+esc(value)+'">'+text+'</button>';
 function status(text){if(el('workshopStatus'))el('workshopStatus').textContent=text;}
 function frame(content){dialog.innerHTML=button('Return to assembly','close')+'<span class="eyebrow">ASSEMBLY / TEACHING SESSION</span>'+content+'<p id="workshopStatus" role="status"></p>';}
 function stop(){clearInterval(timer);clearInterval(poller);}
 async function open(){client=AssemblyAccount.connection();active=true;stop();state=null;if(!dialog.open)dialog.showModal();frame('<h2>Teaching sessions</h2><p>Loading...</p>');try{const {data,error}=await client.from('assembly_roles').select('role').maybeSingle();if(error)throw error;const teacher=data?.role==='professor';const result={data:await rpc('assembly_session_list')};frame('<h2>Teaching sessions</h2><p>Prepare a session, then add its classrooms. Audio/video conferencing is not connected in this release.</p><p>10-minute prebrief · 20-minute negotiation · 15-minute report · 15-minute debrief</p>'+(teacher?'<form id="workshopCreate"><label>Session title<input name="title" required maxlength="100" placeholder="Global health diplomacy workshop"></label><button type="submit" class="primary">Create teaching session</button></form>':'')+button('Open earlier classrooms','legacy')+'<div>'+result.data.map(c=>'<p>'+button(esc(c.title),'session',c.id)+'</p>').join('')+'</div>');}catch(e){status(e.message)}}
 async function load(id){stop();active=true;state=await rpc('assembly_session_snapshot',{target_class:id});topics=state.teacher?await rpc('assembly_topic_catalog'):[];render();timer=setInterval(tick,1000);poller=setInterval(poll,3500)}
 function render(){frame('<h2>Teaching session</h2><div id="workshopUpdates"></div>'+(state.teacher?'<section><h3>Students awaiting approval</h3><p>Verify each student in person or through your agreed communication channel before approving.</p><div id="workshopApprovals"></div></section><details><summary>Professor: message every classroom</summary><form id="workshopBroadcast"><label>Announcement<textarea name="text" required maxlength="1500"></textarea></label><button type="submit" class="primary">Send to all classrooms</button></form></details>':'')+(state.teacher&&state.stage==='preparation'?'<details><summary>Prepare a classroom and assign roles</summary><form id="workshopRoom"><label>Classroom title<input name="title" required maxlength="100" placeholder="Classroom 1"></label><label>Health issue<select name="topic" id="workshopTopic">'+topics.map(t=>'<option value="'+esc(t.id)+'">'+esc(t.title)+'</option>').join('')+'</select></label><label>Number of students<select name="count" id="workshopCount">'+[4,5,6,7,8].map(n=>'<option>'+n+'</option>').join('')+'</select></label><div id="workshopParticipants"></div><div id="workshopBriefs"></div><button type="submit" class="primary">Save prepared classroom</button></form></details>':'')+'<div id="workshopRooms"></div>');participants();updates();approvals().catch(e=>status(e.message));}
 function participants(){if(!el('workshopParticipants'))return;const t=topics.find(t=>t.id===el('workshopTopic').value);const old=[...el('workshopParticipants').querySelectorAll('input')].map(i=>i.value);const oldRoles=[...el('workshopParticipants').querySelectorAll('select')].map(i=>i.value);el('workshopParticipants').innerHTML=Array.from({length:Number(el('workshopCount').value)},(_,i)=>'<fieldset><legend>Student '+(i+1)+'</legend><label>Name<input name="studentName'+i+'" value="'+esc(old[i]||'')+'" required maxlength="80"></label><label>Country or role<select name="studentRole'+i+'" required><option value="">Choose role</option>'+Object.entries(t?.roles||{}).map(([key,b])=>'<option value="'+esc(key)+'" '+(oldRoles[i]===key?'selected':'')+'>'+esc(b.name)+'</option>').join('')+'</select></label></fieldset>').join('');el('workshopBriefs').innerHTML='<details><summary>Professor: review this topic and private role descriptions</summary><p>'+esc(t?.summary)+'</p>'+Object.values(t?.roles||{}).map(b=>'<details><summary>'+esc(b.name)+'</summary>'+Object.entries(b).filter(([k])=>k!=='name').map(([k,v])=>'<p><strong>'+esc(k.replaceAll('_',' '))+'</strong>: '+esc(v)+'</p>').join('')+'</details>').join('')+'</details>';}
 function updates(){offset=Date.parse(state.server_now)-Date.now();el('workshopUpdates').innerHTML='<h3>'+labels[state.stage]+'</h3><p id="workshopClock" role="timer"></p>'+button('Enable bell sound','sound')+'<p id="workshopBell" role="status"></p>'+(state.teacher&&state.stage!=='finished'?button(state.stage==='preparation'?'Begin 10-minute prebrief':'End this stage and begin next','next')+(state.ends?button('Pause timer','pause'):state.remaining!==null?button('Resume timer','resume'):''):'')+'<div class="room-log">'+state.broadcasts.slice(-10).map(m=>'<p><strong>Professor</strong> '+esc(m.text)+'</p>').join('')+'</div>';el('workshopRooms').innerHTML=state.rooms.map(r=>'<article class="room-overview"><h3>'+esc(r.title)+'</h3><p>'+esc(r.topic)+'</p>'+(state.teacher?'<p><strong>Student joining code:</strong> <code>'+esc(r.code)+'</code></p>'+button('Copy student joining code','copyCode',r.id)+'<p class="micro-note">Share this code only with the students listed in this classroom.</p>':'')+'<ul>'+r.participants.map(p=>'<li>Student '+p.number+': '+esc(p.name)+' — '+esc(p.role_name)+' ('+(p.joined?'joined':'awaiting sign-in')+')</li>').join('')+'</ul>'+button('Open classroom','room',r.id)+'</article>').join('');tick();}
 function tick(){if(!state||!el('workshopClock'))return;const secs=state.ends?Math.max(0,Math.ceil((Date.parse(state.ends)-Date.now()-offset)/1000)):state.remaining;el('workshopClock').textContent=secs===null?'Timer not running':Math.floor(secs/60)+':'+String(secs%60).padStart(2,'0')+(state.ends?'':' (paused)');if(state.ends&&secs===0){el('workshopBell').textContent='Time is up. The professor will guide the next stage.';const key=state.class_id+state.ends;if(key!==ringKey){ringKey=key;if(audio?.state==='running'){const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=880;g.gain.setValueAtTime(0.2,audio.currentTime);g.gain.exponentialRampToValueAtTime(0.001,audio.currentTime+1.2);o.start();o.stop(audio.currentTime+1.2);}}}}
 async function approvals(){if(!state?.teacher||!el('workshopApprovals'))return;const requests=await rpc('assembly_entry_requests',{target_class:state.class_id});el('workshopApprovals').innerHTML=requests.map(q=>'<article><p>'+esc(q.name)+' / '+esc(q.room)+' / '+esc(q.role)+'</p><button type="button" class="primary" data-workshop="approve" data-value="'+esc(q.room_id)+'" data-student="'+esc(q.user_id)+'">Approve</button><button type="button" class="secondary" data-workshop="reject" data-value="'+esc(q.room_id)+'" data-student="'+esc(q.user_id)+'">Reject</button></article>').join('')||'<p>No pending requests.</p>';}
 async function poll(){if(loading||!active||!dialog.open||!state)return;loading=true;const id=state.class_id;try{const next=await rpc('assembly_session_snapshot',{target_class:id});if(active&&state?.class_id===id){state=next;updates();await approvals();}}catch(e){status(e.message)}finally{loading=false}}
 dialog.addEventListener('change',e=>{if(['workshopCount','workshopTopic'].includes(e.target.id))participants()});
 dialog.addEventListener('cancel',()=>{active=false;stop()});
 dialog.addEventListener('click',async e=>{const b=e.target.closest('[data-workshop]');if(!b)return;b.disabled=true;try{const a=b.dataset.workshop;if(a==='close'){active=false;stop();dialog.close();return}if(a==='copyCode'){const code=state.rooms.find(r=>r.id===b.dataset.value)?.code;if(!code)throw Error('No classroom code available.');try{await navigator.clipboard.writeText(code);status('Student joining code copied. Share it with this classroom only.');}catch{status('Copy this student joining code: '+code);}return}if(a==='session'){await load(b.dataset.value);return}if(a==='sound'){audio??=new (window.AudioContext||window.webkitAudioContext)();await audio.resume();status('Bell sound enabled on this device.');return}if(a==='legacy'){active=false;stop();dialog.close();await AssemblyRooms.open();return}if(a==='room'){dialog.close();await AssemblyRooms.openRoom(b.dataset.value);return}if(a==='approve'||a==='reject'){await rpc('assembly_approve_entry',{target_room:b.dataset.value,student_user:b.dataset.student,approve:a==='approve'});await poll();return}if(a==='next'&&!confirm('End the current stage and start the next timed stage for all classrooms?'))return;if(['next','pause','resume'].includes(a)){state=await rpc('assembly_session_control',{target_class:state.class_id,command:a,payload:{revision:state.revision}});updates();if(state.stage!=='preparation'&&el('workshopRoom'))el('workshopRoom').closest('details').hidden=true}}catch(e){status(e.message)}finally{b.disabled=false}});
 dialog.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button[type="submit"]');b.disabled=true;try{if(f.id==='workshopCreate'){await load(await rpc('assembly_session_create',{session_title:f.elements.title.value.trim()}));}if(f.id==='workshopRoom'){const n=Number(f.elements.count.value),participants=Array.from({length:n},(_,i)=>({name:f.elements['studentName'+i].value.trim(),role:f.elements['studentRole'+i].value}));if(new Set(participants.map(p=>p.role)).size!==n)throw Error('Choose a different role for every student.');await rpc('assembly_prepare_room',{target_class:state.class_id,room_title:f.elements.title.value.trim(),chosen_topic:f.elements.topic.value,participants});f.reset();participantsRefresh();await poll();status('Classroom prepared. Roles have been saved before students join.');}if(f.id==='workshopBroadcast'){state=await rpc('assembly_session_control',{target_class:state.class_id,command:'broadcast',payload:{text:f.elements.text.value}});f.reset();updates();}}catch(e){status(e.message)}finally{b.disabled=false}});
 function participantsRefresh(){participants()}
 async function lobby(id){active=true;client=AssemblyAccount.connection();if(!dialog.open)dialog.showModal();await load(id);}
 function observe(next){if(next){state=next;offset=Date.parse(next.server_now)-Date.now();tick();}}
 return {open,lobby,observe};
})();
